// El JSON entre estos marcadores se reemplaza con scripts/configure.mjs.
// CONFIG_START
const config = {
  "configuracionLista": false,
  "fuenteAutorizada": false,
  "versionFlujo": "1.2.0",
  "location": "Santiago, Chile",
  "zonasPermitidas": [
    "Santiago",
    "Región Metropolitana"
  ],
  "aceptarRemoto": true,
  "excluirPracticas": true,
  "excluirSenior": false,
  "scoreMinimo": 65,
  "maxOfertasPorEjecucion": 1,
  "maxDetallesPorEjecucion": 10,
  "descripcionMinimaCaracteres": 200,
  "maxDescripcionCaracteres": 16000,
  "geminiMaxOutputTokens": 6000,
  "googleSheetId": "REEMPLAZAR_ID_DOCUMENTO",
  "googleSheetName": "Ofertas",
  "geminiModel": "REEMPLAZAR_MODELO_DISPONIBLE",
  "telegramChatId": "REEMPLAZAR_CHAT_ID",
  "generarPdf": false,
  "latexApiUrl": "",
  "perfilesObjetivo": [
    {
      "id": "perfil_1",
      "nombre": "REEMPLAZAR_CARGO_OBJETIVO",
      "descripcion": "REEMPLAZAR_FUNCIONES_DEL_CARGO_QUE_BUSCAS"
    }
  ],
  "busquedas": [
    {
      "keyword": "REEMPLAZAR_TERMINO_DE_BUSQUEDA",
      "categoria": "perfil_1"
    }
  ],
  "catalogoCv": {
    "candidato": {
      "id": "REEMPLAZAR_ID_CANDIDATO",
      "nombre": "REEMPLAZAR_NOMBRE",
      "titulo": "REEMPLAZAR_TITULO_REAL",
      "resumen": "REEMPLAZAR_RESUMEN_VERIFICADO_SIN_INVENTAR_EXPERIENCIA",
      "ubicacion": "REEMPLAZAR_UBICACION",
      "telefono": "",
      "email": "",
      "linkedin": "",
      "github": ""
    },
    "experienciaProfesionalMesesAprox": 0,
    "experiencias": [
      {
        "id": "experiencia_1",
        "cargo": "REEMPLAZAR_CARGO_O_ELIMINAR_ESTA_EXPERIENCIA",
        "empresa": "REEMPLAZAR_EMPRESA",
        "fechas": "REEMPLAZAR_FECHAS",
        "bullets": [
          {
            "id": "experiencia_1_bullet_1",
            "texto": "REEMPLAZAR_FUNCION_REAL"
          }
        ],
        "herramientas": "",
        "tipoEvidencia": "Experiencia laboral documentada"
      }
    ],
    "proyectos": [
      {
        "id": "proyecto_1",
        "nombre": "REEMPLAZAR_PROYECTO_O_ELIMINARLO",
        "descripcion": "REEMPLAZAR_DESCRIPCION_REAL",
        "herramientas": ""
      }
    ],
    "habilidades": {
      "Competencias verificadas": [
        "REEMPLAZAR_HABILIDADES_REALES"
      ]
    },
    "certificaciones": [],
    "educacion": {
      "titulo": "REEMPLAZAR_ESTUDIOS_REALES",
      "estado": "REEMPLAZAR_ESTADO",
      "institucion": "REEMPLAZAR_INSTITUCION",
      "detalle": ""
    },
    "idiomas": [
      {
        "idioma": "Español",
        "nivel": "REEMPLAZAR_NIVEL_REAL"
      }
    ],
    "criteriosEvidencia": [
      "Los proyectos no equivalen a años de experiencia laboral.",
      "Un curso preparatorio no equivale a aprobar un examen de certificación oficial.",
      "No atribuir funciones, licencias ni competencias profesionales sin evidencia documentada."
    ]
  }
};
// CONFIG_END
const fail = message => { throw new Error('Configuración: ' + message); };
if (config.configuracionLista !== true) fail('completa tu perfil y cambia configuracionLista a true.');
if (config.fuenteAutorizada !== true) fail('verifica las condiciones de la fuente antes de autorizar su uso.');
if (/REEMPLAZAR_/.test(JSON.stringify(config))) fail('quedan campos REEMPLAZAR_.');
if (!/^[a-zA-Z0-9_-]{20,}$/.test(config.googleSheetId || '')) fail('googleSheetId debe ser el ID, no el enlace completo.');
if (!String(config.googleSheetName || '').trim()) fail('falta el nombre exacto de la pestaña.');
if (!/^-?\d+$/.test(String(config.telegramChatId || ''))) fail('telegramChatId debe ser numérico.');
if (!/^[a-zA-Z0-9._-]+$/.test(config.geminiModel || '')) fail('indica el nombre de un modelo disponible, sin models/.');
for (const [key, min, max] of [['scoreMinimo',45,100],['maxOfertasPorEjecucion',1,30],['maxDetallesPorEjecucion',1,100],['descripcionMinimaCaracteres',120,2000],['maxDescripcionCaracteres',2000,30000],['geminiMaxOutputTokens',2000,16000]]) {
  if (!Number.isInteger(config[key]) || config[key] < min || config[key] > max) fail(key + ' fuera del rango ' + min + '..' + max);
}
if (config.maxDetallesPorEjecucion < config.maxOfertasPorEjecucion) fail('maxDetallesPorEjecucion debe ser mayor o igual que maxOfertasPorEjecucion.');
for (const key of ['aceptarRemoto','excluirPracticas','excluirSenior','generarPdf']) if (typeof config[key] !== 'boolean') fail(key + ' debe ser booleano.');
if (!String(config.location || '').trim()) fail('falta location.');
if (!Array.isArray(config.zonasPermitidas) || config.zonasPermitidas.some(v => typeof v !== 'string' || !v.trim())) fail('zonasPermitidas debe ser una lista de textos.');
if (!Array.isArray(config.busquedas) || !config.busquedas.length || config.busquedas.length > 12) fail('configura entre 1 y 12 búsquedas.');
if (!Array.isArray(config.perfilesObjetivo) || !config.perfilesObjetivo.length || config.perfilesObjetivo.length > 12) fail('configura entre 1 y 12 perfilesObjetivo.');
const perfiles = new Set();
for (const perfil of config.perfilesObjetivo) {
  if (!/^[a-z][a-z0-9_]*$/.test(perfil?.id || '') || perfiles.has(perfil.id) || !perfil.nombre?.trim() || !perfil.descripcion?.trim()) fail('perfil objetivo incompleto, repetido o con ID inválido.');
  perfiles.add(perfil.id);
}
for (const b of config.busquedas) if (typeof b.keyword !== 'string' || !b.keyword.trim() || !perfiles.has(b.categoria)) fail('cada búsqueda debe apuntar al ID de un perfilObjetivo.');
const c = config.catalogoCv;
if (!c?.candidato?.id || !c.candidato.nombre || !c.candidato.titulo || !c.candidato.resumen || !c.candidato.ubicacion) fail('faltan datos del candidato.');
if (!Number.isFinite(c.experienciaProfesionalMesesAprox) || c.experienciaProfesionalMesesAprox < 0) fail('meses de experiencia inválidos.');
for (const key of ['experiencias','proyectos','certificaciones','idiomas','criteriosEvidencia']) if (!Array.isArray(c[key])) fail(key + ' debe ser una lista.');
if (!c.educacion || typeof c.educacion !== 'object' || !c.habilidades || Array.isArray(c.habilidades) || typeof c.habilidades !== 'object') fail('educacion y habilidades deben ser objetos.');
if (Object.values(c.habilidades).some(v => !Array.isArray(v) || v.some(s => typeof s !== 'string' || !s.trim()))) fail('habilidades debe contener listas de textos.');
const ids = new Set();
const checkId = id => { if (!/^[a-z0-9_]+$/.test(id || '') || ids.has(id)) fail('ID vacío, repetido o inválido: ' + id); ids.add(id); };
for (const e of c.experiencias) {
  checkId(e.id);
  if (!e.cargo || !e.empresa || !e.fechas || !Array.isArray(e.bullets)) fail('experiencia incompleta.');
  for (const b of e.bullets) { checkId(b.id); if (!b.texto?.trim()) fail('bullet sin texto.'); }
}
for (const p of c.proyectos) { checkId(p.id); if (!p.nombre || !p.descripcion) fail('proyecto incompleto.'); }
for (const cert of c.certificaciones) { checkId(cert.id); if (!cert.titulo || !cert.institucion) fail('certificación incompleta.'); }
for (const idioma of c.idiomas) if (!idioma.idioma || !idioma.nivel) fail('idioma incompleto.');
if (config.generarPdf && !/^https?:\/\/[^\s]+$/.test(config.latexApiUrl || '')) fail('activa PDF solo con una API de compilación propia configurada.');
return [{ json: config }];

// Los campos ya pertenecen a una sola tarjeta; nunca unir arrays por posición.
return $input.all().flatMap((entry,index)=>{
  const data=entry.json;
  if (data._sinResultados) return [];
  for (const key of ['empresa','ubicacion','fecha_publicacion']) if (data[key] == null) data[key]='';
  for (const key of ['titulo','empresa','ubicacion','fecha_publicacion','url']) {
    if (typeof data[key] !== 'string') throw new Error('Fuente: campo de tarjeta inválido: '+key);
  }
  if (!data.titulo.trim() || !data.url.trim()) throw new Error('Fuente: tarjeta incompleta.');
  const clean=v=>v.replace(/\s+/g,' ').trim();
  return [{json:{titulo:clean(data.titulo),empresa:clean(data.empresa),ubicacion:clean(data.ubicacion),
    fecha_publicacion:data.fecha_publicacion.trim(),url:data.url.replace(/&amp;/g,'&').trim(),fuente:'LinkedIn',
    keyword_origen:String(data.keyword_origen||''),categoria_origen:String(data.categoria_origen||''),
    orden_busqueda:Number(data.orden_busqueda||0)},pairedItem:{item:index}}];
});

const porId = new Map();
  const entradas = $input.all();
  const listaUnica = valores => [
    ...new Set(valores.filter(Boolean).map(String)),
  ];

  const normalizarUrlEntrada = valor => {
    let url = String(valor || '')
      .replace(/&amp;/gi, '&')
      .replace(/\s+/g, '')
      .trim();

    if (!url) return '';

    if (url.startsWith('//')) {
      url = 'https:' + url;
    } else if (url.startsWith('/')) {
      url = 'https://www.linkedin.com' + url;
    } else if (!/^https?:\/\//i.test(url)) {
      if (/^(?:www\.|[a-z]{2,3}\.)?linkedin\.com\//i.test(url)) {
        url = 'https://' + url;
      } else {
        return '';
      }
    }

    if (!/^https?:\/\/(?:www\.|[a-z]{2,3}\.)?linkedin\.com(?=\/)/i.test(url)) return '';
    return url;
  };

  for (const entrada of entradas) {
    const item = entrada.json || {};
    const titulo = String(item.titulo || '').replace(/\s+/g, ' ').trim();
    const url = normalizarUrlEntrada(item.url);
    if (!titulo || !url) continue;

    // LinkedIn publica dos formatos habituales:
    // /jobs/view/4459762468 y /jobs/view/nombre-del-cargo-4459762468.
    // También puede entregar el ID en currentJobId o jobId.
    const match =
      url.match(/[?&](?:currentJobId|jobId)=(\d{6,})(?=&|$)/i) ||
      url.match(/\/jobs\/view\/[^/?#]*?(\d{6,})(?=[/?#]|$)/i) ||
      url.match(/\/jobs\/(\d{6,})(?=[/?#]|$)/i);

    const numero = match ? match[1] : '';
    if (!numero) continue;
    let urlCanonica = '';

    if (numero) {
      urlCanonica = 'https://www.linkedin.com/jobs/view/' + numero + '/';
    } else {
      urlCanonica = url
        .split('#')[0]
        .split('?')[0]
        .replace(/\/+$/, '')
        .replace(
          /^https?:\/\/(?:www\.|[a-z]{2,3}\.)?linkedin\.com/i,
          'https://www.linkedin.com'
        );
    }

    const idExterno = numero ? 'linkedin-' + numero : urlCanonica;
    if (!idExterno) continue;

    const anterior = porId.get(idExterno);
    const keywords = listaUnica([
      ...(anterior?.keywords_origen || []),
      item.keyword_origen,
    ]);
    const categorias = listaUnica([
      ...(anterior?.categorias_origen || []),
      item.categoria_origen,
    ]);

    const candidato = {
      ...(anterior || item),
      ...item,
      titulo,
      url: urlCanonica,
      id_externo: idExterno,
      keywords_origen: keywords,
      categorias_origen: categorias,
      fecha_deteccion: anterior?.fecha_deteccion || new Date().toISOString(),
    };

    if (!anterior) {
      porId.set(idExterno, candidato);
      continue;
    }

    const fechaAnterior = Date.parse(anterior.fecha_publicacion || '') || 0;
    const fechaNueva = Date.parse(item.fecha_publicacion || '') || 0;
    porId.set(
      idExterno,
      fechaNueva >= fechaAnterior
        ? candidato
        : {
            ...candidato,
            ...anterior,
            keywords_origen: keywords,
            categorias_origen: categorias,
          }
    );
  }

  const salida = [...porId.values()].map(item => ({ json: item }));

  if (entradas.length > 0 && salida.length === 0) {
    throw new Error(
      'Se recibieron ' + entradas.length +
      ' ofertas, pero ninguna tenía un título y una URL reconocibles.'
    );
  }

  return salida;

const rows=$input.all().map(i=>i.json || {});
const idsExistentes=[...new Set(rows.filter(r=>!/^ERROR_/i.test(String(r.estado||''))).map(r=>r.id_externo).filter(Boolean).map(String))];
// La fecha del último intento guardado da prioridad a categorías menos atendidas.
const ultimoTurnoPorCategoria=Object.create(null);
for (const row of rows) {
  const category=String(row.categoria_seleccionada||'');
  const when=Date.parse(row.fecha_deteccion)||0;
  if (category) ultimoTurnoPorCategoria[category]=Math.max(ultimoTurnoPorCategoria[category]||0,when);
}
return [{json:{idsExistentes,ultimoTurnoPorCategoria}}];

const c=$('Configuración').first().json;
const history=$('IDs existentes').first().json;
const ids=new Set(history.idsExistentes || []);
const last=history.ultimoTurnoPorCategoria || {};
const norm=v=>String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const cats=[...new Set(c.busquedas.map(b=>b.categoria))].sort((a,b)=>(last[a]||0)-(last[b]||0));
const groups=Object.fromEntries(cats.map(k=>[k,[]]));
const candidates=$('Eliminar duplicados del lote').all().map(i=>i.json).filter(i=>{
  if (!i.id_externo || ids.has(i.id_externo)) return false;
  const title=norm(i.titulo),zone=norm(i.ubicacion);
  if (c.excluirPracticas && /\b(practica|practicante|pasantia|internship|intern|becario)\b/.test(title)) return false;
  if (c.excluirSenior && /\b(senior|semisenior|sr|ssr|lead|principal|staff|manager|jefe|director|gerente)\b/.test(title)) return false;
  // Con remoto habilitado la ciudad de la tarjeta no basta para descartar.
  return c.aceptarRemoto || !zone || !c.zonasPermitidas.length || c.zonasPermitidas.some(z=>zone.includes(norm(z)));
}).sort((a,b)=>(Date.parse(b.fecha_publicacion)||0)-(Date.parse(a.fecha_publicacion)||0));
for (const item of candidates) {
  const available=(item.categorias_origen||[item.categoria_origen]).filter(k=>Object.hasOwn(groups,k));
  const category=(available.length?available:[cats[0]]).sort((a,b)=>groups[a].length-groups[b].length || cats.indexOf(a)-cats.indexOf(b))[0];
  groups[category].push({...item,categoria_seleccionada:category});
}
const result=[];
while(result.length<c.maxDetallesPorEjecucion){
  let added=false;
  for(const category of cats){
    if(groups[category].length){result.push({json:groups[category].shift()});added=true;}
    if(result.length>=c.maxDetallesPorEjecucion)break;
  }
  if(!added)break;
}
return result;

const item = $input.item.json || {};
  return {
    json: {
      url: String(item.url || ''),
      _original: item,
    },
  };

const original=$('Conservar oferta').item.json._original;
if (!original?.id_externo) throw new Error('Oferta original no vinculada.');
const c=$('Configuración').first().json;
const descripcion=String($input.item.json.descripcion||'').replace(/\s+/g,' ').trim().slice(0,c.maxDescripcionCaracteres);
const norm=v=>String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const content=norm(original.ubicacion+' '+descripcion);
const modalidad=/\bhibrid[oa]\b/.test(content)?'Híbrido':/\b(remoto|remote|teletrabajo)\b/.test(content)?'Remoto':/\b(presencial|onsite|on site)\b/.test(content)?'Presencial':'No especificado';
const zone=norm(original.ubicacion);
const allowed=!zone || !c.zonasPermitidas.length || c.zonasPermitidas.some(z=>zone.includes(norm(z))) || (c.aceptarRemoto && modalidad==='Remoto');
let motivo='';
if (descripcion.length<c.descripcionMinimaCaracteres) motivo='DETALLE_INSUFICIENTE';
else if(c.excluirPracticas && /\b(seguro escolar|convenio de practica|practicante|pasantia|internship)\b/.test(content)) motivo='PRACTICA_EXCLUIDA';
else if(!allowed) motivo='FUERA_DE_ZONA';
return {json:{...original,descripcion,modalidad,detalle_valido:!motivo,_motivoDetalle:motivo}};

const item = $input.item.json || {};
  const original = {
    ...item,
    descripcion: String(item.descripcion || '').slice(
      0,
      Number($('Configuración').first().json.maxDescripcionCaracteres || 16000)
    ),
  };

  return { json: { ...original, _original: original } };

