const item = $input.item.json;
if (typeof item.data !== 'string') throw new Error('Fuente: la búsqueda no devolvió HTML.');
const html = item.data.trim();
// Detectar páginas de autenticación/bloqueo antes de tratar un resultado como vacío.
if (/<(?:form|iframe)\b[^>]*(?:checkpoint|authwall|login|captcha|challenge)/i.test(html) || /(?:id|class)\s*=\s*["'][^"']*(?:authwall|checkpoint|captcha|challenge-page|login__form)/i.test(html)) {
  throw new Error('Fuente: autenticación o bloqueo. Detén el flujo y revisa el acceso.');
}
// El endpoint guest puede devolver únicamente espacios cuando no quedan resultados.
const empty = !html || /class\s*=\s*["'][^"']*\b(?:jobs-search-no-results-banner|jobs-search__no-results)\b/i.test(html);
const cards = /class\s*=\s*["'][^"']*\bbase-card\b/i.test(html);
if (!empty && !cards) throw new Error('Fuente: HTML de búsqueda no reconocido; revisa los selectores.');
return {json:{...item,_busquedaVacia:empty && !cards}};

const input = $input.first().json;
const cards = input.tarjetas;
const empty = $('Validar búsqueda').item.json._busquedaVacia;
if (!Array.isArray(cards)) throw new Error('Fuente: extracción de tarjetas inválida.');
if (!cards.length) {
  if (!empty) throw new Error('Fuente: había tarjetas, pero el selector no extrajo ninguna.');
  // Un centinela conserva el retorno del bucle cuando una búsqueda no tiene ofertas.
  return [{json:{data:'',_sinResultados:true},pairedItem:{item:0}}];
}
return cards.map(data=>({json:{data,_sinResultados:false},pairedItem:{item:0}}));

const item=$input.item.json;
const c=$('Configuración').first().json;
if (!item.id_externo || !item._motivoDetalle) throw new Error('Descarte de detalle incompleto.');
return {json:{...item,candidato_id:c.catalogoCv.candidato.id,score:0,decision:'DESCARTAR',perfil_cv:'NO_EVALUADO',
  estado:item._motivoDetalle,justificacion:'Sin análisis IA: '+item._motivoDetalle+'. Cambia estado a ERROR_DETALLE para reintentar si el contenido fue corregido.',
  requisitos_faltantes:'No evaluados.',titulo_cv:c.catalogoCv.candidato.titulo,
  keyword_origen:(item.keywords_origen||[]).join(', ') || item.keyword_origen || '',_seleccion:null}};
